entries[57761] = { ["name"] = "Feuerball!", ["text"] = "100 Meter Reichweite\nSofort\nEuer nächstes Wirken von 'Feuerball' oder 'Frostfeuerblitz' ist ein Spontanzauber und kostet kein Mana.\nModifies Power Cost -1000%:\nFeuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Frostfeuerblitz , Frostfeuerblitz\n\nModifies Cast Time -100000%:\nFeuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Feuerball , Frostfeuerblitz , Frostfeuerblitz" }
